```tsx
import { useEffect, useState } from "react";
import { listen } from "@tauri-apps/api/event";
import { invoke } from "@tauri-apps/api/core";

// ------------------------------------------------------------------
// Tipos
// ------------------------------------------------------------------

type EventKind = "started" | "progress" | "finished" | "batch_complete";

interface StartedData {
  url: string;
  downloadId: number;
  totalBytes: number;
}

interface ProgressData {
  downloadId: number;
  fileIndex: number;              // 0-based
  downloadedBytes: number;
  fileName: string;
  instantSpeed?: number;          // bytes/s, chega só no fim do arquivo
}

interface FinishedData {
  downloadId: number;
  fileName: string;
}

interface CompleteData {
  text: string;
}

type DownloadEvent =
  | { event: "started"; data: StartedData }
  | { event: "progress"; data: ProgressData }
  | { event: "finished"; data: FinishedData }
  | { event: "batch_complete"; data: CompleteData };

// ------------------------------------------------------------------
// Componente
// ------------------------------------------------------------------

function formatBytes(bytes: number): string {
  if (bytes === 0) return "0 B";
  const k = 1024;
  const units = ["B", "KB", "MB", "GB", "TB"];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  const value = bytes / Math.pow(k, i);
  return `${value.toFixed(2)} ${units[i]}`;
}

const DownloadFile = () => {
  const [message, setMessage] = useState("");
  const [currentFile, setCurrentFile] = useState(0);          // qual arquivo está em andamento
  const [filesCompleted, setFilesCompleted] = useState(0);    // quantos terminaram
  const [downloadedBytes, setDownloadedBytes] = useState(0);  // bytes acumulados (globais)
  const [globalTotalBytes, setGlobalTotalBytes] = useState(0); // soma dos tamanhos conhecidos
  const [downloadSpeed, setDownloadSpeed] = useState(0);      // bytes/s (última medição do arquivo)
  const [isDownloading, setIsDownloading] = useState(false);

  useEffect(() => {
    const unsub = listen<DownloadEvent>("download_event", (event) => {
      const { event: kind, data } = event.payload;

      switch (kind) {
        case "started": {
          const d = data;
          // acumula o tamanho total (para a barra) e mostra a URL
          setGlobalTotalBytes((v) => v + (d.totalBytes ?? 0));
          setMessage(
            d.url
              ? `⬇ Baixando ${d.url}\n ${(d.totalBytes ?? 0) / (1024 * 1024)}.${(d.totalBytes ?? 0) % (1024 * 1024) / 1024} MB`
              : ""
          );
          break;
        }

        case "progress": {
          const p = data;
          setDownloadedBytes(p.downloadedBytes);
          setCurrentFile(Math.max(currentFile, p.fileIndex) + 1);
          // velocidade só é útil no último tick do arquivo
          if (p.instantSpeed != null) setDownloadSpeed(p.instantSpeed);
          break;
        }

        case "finished": {
          // conta o arquivo concluído e avança o contador visual
          setCurrentFile((prev) => Math.max(prev, data.downloadId));
          setFilesCompleted((prev) => prev + 1);
          break;
        }

        case "batch_complete": {
          setMessage(data.text);
          break;
        }
      }
    });

    // limpa os escutas ao desmontar o componente
    return () => {
      unsub.then((fn) => fn()).catch(() => {});
    };
  }, []);

  const startDownload = async () => {
    if (isDownloading) return;

    setIsDownloading(true);
    try {
      // IMPORTANTE: criamos o canal ÚNICO fora do invoke e passamos o topo
      // { on_event: onEvent } — nunca aninhado dentro de "args"
      const onEvent = new Channel<DownloadEvent>();
      await invoke("start_downloads", { on_event: onEvent });
    } catch (err) {
      setIsDownloading(false);
      setMessage(
        `Falha ao iniciar: ${err instanceof Error ? err.message : String(err)}`
      );
    }
  };

  const progressPercent =
    globalTotalBytes > 0 ? Math.min(100, (downloadedBytes / globalTotalBytes) * 100) : 0;

  return (
    <>
      <div className="absolute bottom-20 rounded-lg w-[71%] h-[8%] flex flex-col justify-between items-center">
        <button
          onClick={startDownload}
          disabled={isDownloading}
          className="bg-blue-500 text-white rounded p-2 mb-2 disabled:bg-gray-400"
        >
          {isDownloading ? "⬇ Baixando…" : "Iniciar Download"}
        </button>
      </div>

      <div className="absolute bottom-3 rounded-lg w-[71%] flex flex-col items-center gap-2">
        <div className="w-full flex items-center text-[14px] font-bold text-white text-center">
          <span>{message}</span>
          {isDownloading && currentFile > 0 && (
            <span className="ml-2 text-orange-500">
              Arquivo {currentFile} em andamento
            </span>
          )}
        </div>

        {/* velocímetro */}
        {isDownloading && downloadSpeed > 0 && (
          <span className="text-[10px] font-bold text-yellow-600 text-right mt-1">
            {formatBytes(downloadSpeed)}/s
          </span>
        )}

        {/* barra de progresso */}
        <div className="w-[95%] h-6 rounded-md bg-[#0E1622]/[0.95] text-green-600 flex items-center shadow-inner shadow-gray-800">
          <div
            className="bg-[#1164CA]/[0.95] ml-1 rounded-md h-4"
            style={{ width: `${progressPercent}%` }}
          />
        </div>
      </div>
    </>
  );
};

export default DownloadFile;
```

