          {isDownloading && currentFile > 0 && (
            <span className="ml-2 text-orange-500">
              Arquivo {currentFile} em andamento
            </span>
          )}
        </div>

        {/* velocímetro */}
        {isDownloading && downloadSpeed > 0 && (
          <span className="text-[10px] font-bold text-yellow-600 text-right mt-1">
            {formatBytes(downloadSpeed)}/s
          </span>
        )}

        {/* barra de progresso */}
        <div className="w-[95%] h-6 rounded-md bg-[#0E1622]/[0.95] text-green-600 flex items-center shadow-inner shadow-gray-800">
          <div
            className="bg-[#1164CA]/[0.95] ml-1 rounded-md h-4"
            style={{ width: `${progressPercent}%` }}
          />
        </div>
      </div>
    </>
  );
};

export default DownloadFile;
